  if (phase === 'hidden') return null;

  return (
    <section
      data-testid="dice-tray"
      className={[
        'dice-tray',
        `dice-tray--${phase}`,
        frameBreak ? 'dice-tray--center-stage' : 'dice-tray--upper-center',
        reducedMotion ? 'dice-tray--reduced-motion' : '',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
    >
      <svg
        data-testid="d20-die"
        aria-hidden="true"
        viewBox="0 0 100 100"
        className="dice-tray__die d20-die"
      >
        <g
          data-testid="d20-shell"
          className={`d20-shell ${rolling ? 'dice-tray__die--rolling d20-die--tumbling' : 'd20-die--settled'}`}
        >
          <polygon
            data-testid="d20-silhouette"
            points={SILHOUETTE_POINTS}
            fill="currentColor"
            fillOpacity={0.08}
            stroke="currentColor"
            strokeWidth={4}
            strokeLinejoin="round"
          />
          {VERTICES.map(([x, y], index) => (
            <line
              key={index}
              data-testid="d20-facet"
              x1="50"
              y1="50"
              x2={x}
              y2={y}
              stroke="currentColor"
              strokeWidth={2}
              strokeOpacity={0.55}
            />
          ))}
        </g>
        <text
          data-testid="dice-face"
          x="50"
          y="60"
          textAnchor="middle"
          fontSize={face === '?' ? 30 : 26}
          fontWeight={700}
          fill="currentColor"
        >
          {face}
        </text>
      </svg>
      {children}
    </section>
  );
