  const durationsFor = (index: number): BeatDurations =>
    sequence.pace === 'brisk' || index > 0 ? BRISK : CINEMATIC;

  const finishGroup = (index: number) => {
    setReleasedGroupCount((current) => Math.max(current, index + 1));
